CREATE TABLE IF NOT EXISTS users(user_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,display_name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS roles(role_code VARCHAR(11) PRIMARY KEY,CHECK(role_code IN('ADMIN','MAINTAINER','CONTRIBUTOR','BACKER'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_roles(user_id BIGINT UNSIGNED NOT NULL,role_code VARCHAR(11) NOT NULL,PRIMARY KEY(user_id,role_code),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(role_code) REFERENCES roles(role_code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS repositories(repository_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,repository_name VARCHAR(100) NOT NULL UNIQUE,required_approvals TINYINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CONSTRAINT ck_required_approvals CHECK(required_approvals BETWEEN 1 AND 3)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS repository_maintainers(repository_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(repository_id,user_id),FOREIGN KEY(repository_id) REFERENCES repositories(repository_id),FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS labels(label_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,label_name VARCHAR(40) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS issues(issue_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,repository_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,issue_kind VARCHAR(7) NOT NULL,difficulty VARCHAR(6) NOT NULL,status VARCHAR(9) NOT NULL DEFAULT 'OPEN',is_disputed BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),bounty_deadline DATETIME(6) NOT NULL,deadline_extended BOOLEAN NOT NULL DEFAULT FALSE,resolved_at DATETIME(6),FOREIGN KEY(repository_id) REFERENCES repositories(repository_id),FOREIGN KEY(created_by) REFERENCES users(user_id),CHECK(issue_kind IN('BUG','FEATURE')),CHECK(difficulty IN('EASY','MEDIUM','HARD')),CHECK(status IN('OPEN','CLAIMED','IN_REVIEW','RESOLVED','CLOSED')),INDEX ix_issues_deadline(status,is_disputed,bounty_deadline,issue_id),INDEX ix_issues_repository_status(repository_id,status,issue_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS issue_labels(issue_id BIGINT UNSIGNED NOT NULL,label_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(issue_id,label_id),FOREIGN KEY(issue_id) REFERENCES issues(issue_id),FOREIGN KEY(label_id) REFERENCES labels(label_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS accounts(account_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,account_kind VARCHAR(8) NOT NULL,issuance_slot TINYINT GENERATED ALWAYS AS(IF(account_kind='ISSUANCE',1,NULL)) STORED UNIQUE,CHECK(account_kind IN('WALLET','ESCROW','ISSUANCE'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wallets(user_id BIGINT UNSIGNED PRIMARY KEY,account_id BIGINT UNSIGNED NOT NULL UNIQUE,balance DECIMAL(12,2) NOT NULL DEFAULT 0.00,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(account_id) REFERENCES accounts(account_id),CONSTRAINT ck_wallet_balance CHECK(balance>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS escrows(issue_id BIGINT UNSIGNED PRIMARY KEY,account_id BIGINT UNSIGNED NOT NULL UNIQUE,held_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,status VARCHAR(7) NOT NULL DEFAULT 'ACTIVE',FOREIGN KEY(issue_id) REFERENCES issues(issue_id),FOREIGN KEY(account_id) REFERENCES accounts(account_id),CONSTRAINT ck_escrow_held CHECK(held_amount>=0),CHECK(status IN('ACTIVE','FROZEN','SETTLED'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS claims(claim_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,issue_id BIGINT UNSIGNED NOT NULL,claimant_id BIGINT UNSIGNED NOT NULL,status VARCHAR(9) NOT NULL DEFAULT 'ACTIVE',claimed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),expires_at DATETIME(6) NOT NULL,active_issue_id BIGINT UNSIGNED GENERATED ALWAYS AS(IF(status IN('ACTIVE','SUBMITTED'),issue_id,NULL)) STORED UNIQUE,FOREIGN KEY(issue_id) REFERENCES issues(issue_id),FOREIGN KEY(claimant_id) REFERENCES users(user_id),CHECK(status IN('ACTIVE','SUBMITTED','COMPLETED','EXPIRED','CANCELLED')),INDEX ix_claims_expiry(status,expires_at,issue_id,claim_id),INDEX ix_claims_issue_status(issue_id,status,claim_id),INDEX ix_claims_claimant(claimant_id,issue_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pull_requests(pr_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,claim_id BIGINT UNSIGNED NOT NULL UNIQUE,title VARCHAR(200) NOT NULL,status VARCHAR(9) NOT NULL DEFAULT 'SUBMITTED',submitted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),merged_at DATETIME(6),share_revision INT UNSIGNED NOT NULL DEFAULT 1,FOREIGN KEY(claim_id) REFERENCES claims(claim_id),CHECK(status IN('SUBMITTED','MERGED','REJECTED','CANCELLED'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pr_contributors(pr_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,share_percent DECIMAL(5,2) NOT NULL,PRIMARY KEY(pr_id,user_id),FOREIGN KEY(pr_id) REFERENCES pull_requests(pr_id),FOREIGN KEY(user_id) REFERENCES users(user_id),CONSTRAINT ck_share_percent CHECK(share_percent>0 AND share_percent<=100),INDEX ix_pr_contributors_user(user_id,pr_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pr_reviews(review_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,pr_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,decision VARCHAR(15) NOT NULL,comment_text VARCHAR(2000) NOT NULL,share_revision INT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(pr_id) REFERENCES pull_requests(pr_id),FOREIGN KEY(reviewer_id) REFERENCES users(user_id),CHECK(decision IN('APPROVE','REQUEST_CHANGES')),INDEX ix_pr_reviews_latest(pr_id,share_revision,reviewer_id,created_at,review_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS milestones(milestone_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,issue_id BIGINT UNSIGNED NOT NULL,sequence_no SMALLINT UNSIGNED NOT NULL,title VARCHAR(100) NOT NULL,percent DECIMAL(5,2) NOT NULL,status VARCHAR(9) NOT NULL DEFAULT 'PENDING',UNIQUE(issue_id,sequence_no),FOREIGN KEY(issue_id) REFERENCES issues(issue_id),CONSTRAINT ck_milestone_percent CHECK(percent>0 AND percent<=100),CHECK(sequence_no BETWEEN 1 AND 10),CHECK(status IN('PENDING','RELEASED','CANCELLED'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pledges(pledge_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,issue_id BIGINT UNSIGNED NOT NULL,backer_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(18) NOT NULL DEFAULT 'HELD',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(issue_id) REFERENCES issues(issue_id),FOREIGN KEY(backer_id) REFERENCES users(user_id),CONSTRAINT ck_pledge_min CHECK(amount>=10),CHECK(status IN('HELD','PARTIALLY_RELEASED','RELEASED','REFUNDED','PARTIALLY_REFUNDED')),INDEX ix_pledges_issue_fifo(issue_id,created_at,pledge_id),INDEX ix_pledges_backer(backer_id,issue_id,pledge_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS operation_requests(operation_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,actor_key BIGINT UNSIGNED NOT NULL,request_key CHAR(36) NOT NULL,operation_kind VARCHAR(40) NOT NULL,payload_hash BINARY(32) NOT NULL,result_json JSON NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(actor_key,request_key)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS journal_transactions(transaction_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,operation_id BIGINT UNSIGNED NOT NULL UNIQUE,transaction_kind VARCHAR(8) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(operation_id) REFERENCES operation_requests(operation_id),CHECK(transaction_kind IN('TOP_UP','PLEDGE','RELEASE','REFUND'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ledger_entries(entry_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,transaction_id BIGINT UNSIGNED NOT NULL,account_id BIGINT UNSIGNED NOT NULL,signed_amount DECIMAL(12,2) NOT NULL,FOREIGN KEY(transaction_id) REFERENCES journal_transactions(transaction_id),FOREIGN KEY(account_id) REFERENCES accounts(account_id),CHECK(signed_amount<>0),INDEX ix_ledger_entries_account(account_id,entry_id),INDEX ix_ledger_entries_transaction(transaction_id,entry_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS releases(release_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,milestone_id BIGINT UNSIGNED NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,transaction_id BIGINT UNSIGNED NOT NULL UNIQUE,released_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(milestone_id) REFERENCES milestones(milestone_id),FOREIGN KEY(transaction_id) REFERENCES journal_transactions(transaction_id),CONSTRAINT ck_release_amount CHECK(amount>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS release_funding(release_id BIGINT UNSIGNED NOT NULL,pledge_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,PRIMARY KEY(release_id,pledge_id),FOREIGN KEY(release_id) REFERENCES releases(release_id),FOREIGN KEY(pledge_id) REFERENCES pledges(pledge_id),CHECK(amount>0),INDEX ix_release_funding_pledge(pledge_id,release_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payouts(release_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,PRIMARY KEY(release_id,user_id),FOREIGN KEY(release_id) REFERENCES releases(release_id),FOREIGN KEY(user_id) REFERENCES users(user_id),CONSTRAINT ck_payout_amount CHECK(amount>=0),INDEX ix_payouts_user(user_id,release_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS refunds(refund_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,pledge_id BIGINT UNSIGNED NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,reason VARCHAR(10) NOT NULL,transaction_id BIGINT UNSIGNED NOT NULL,refunded_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(pledge_id) REFERENCES pledges(pledge_id),FOREIGN KEY(transaction_id) REFERENCES journal_transactions(transaction_id),CONSTRAINT ck_refund_amount CHECK(amount>0),CHECK(reason IN('WITHDRAWAL','DEADLINE','CLOSURE','DISPUTE'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS disputes(dispute_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,issue_id BIGINT UNSIGNED NOT NULL,opened_by BIGINT UNSIGNED NOT NULL,reason_text VARCHAR(2000) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'OPEN',opened_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),ruled_by BIGINT UNSIGNED,ruled_at DATETIME(6),ruling_text VARCHAR(2000),losing_user_id BIGINT UNSIGNED,open_issue_id BIGINT UNSIGNED GENERATED ALWAYS AS(IF(status='OPEN',issue_id,NULL)) STORED UNIQUE,FOREIGN KEY(issue_id) REFERENCES issues(issue_id),FOREIGN KEY(opened_by) REFERENCES users(user_id),FOREIGN KEY(ruled_by) REFERENCES users(user_id),FOREIGN KEY(losing_user_id) REFERENCES users(user_id),CHECK(status IN('OPEN','RULED_RESUME','RULED_REFUND'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reputation_events(reputation_event_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,repository_id BIGINT UNSIGNED NOT NULL,event_kind VARCHAR(12) NOT NULL,source_id BIGINT UNSIGNED NOT NULL,points SMALLINT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(repository_id) REFERENCES repositories(repository_id),UNIQUE(user_id,event_kind,source_id),CHECK(event_kind IN('PR_MERGED','PR_REJECTED','DISPUTE_LOST')),INDEX ix_reputation_events_scope(repository_id,user_id,reputation_event_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log(audit_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,entity_type VARCHAR(20) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,field_name VARCHAR(20) NOT NULL,old_value VARCHAR(30),new_value VARCHAR(30) NOT NULL,actor_id BIGINT UNSIGNED,actor_kind VARCHAR(6) NOT NULL,operation_id BIGINT UNSIGNED NOT NULL,changed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(actor_id) REFERENCES users(user_id),FOREIGN KEY(operation_id) REFERENCES operation_requests(operation_id),INDEX ix_audit_log_entity(entity_type,entity_id,changed_at,audit_id),INDEX ix_audit_log_time(changed_at,audit_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS content_outbox(event_id CHAR(36) PRIMARY KEY,operation_id BIGINT UNSIGNED NOT NULL,issue_id BIGINT UNSIGNED NOT NULL,collection_name VARCHAR(13) NOT NULL,payload_json JSON NOT NULL,delivery_status VARCHAR(9) NOT NULL DEFAULT 'PENDING',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),delivered_at DATETIME(6),FOREIGN KEY(operation_id) REFERENCES operation_requests(operation_id),FOREIGN KEY(issue_id) REFERENCES issues(issue_id),CHECK(collection_name IN('issue_bodies','comments','code_snippets','commit_logs')),CHECK(delivery_status IN('PENDING','DELIVERED')),INDEX ix_content_outbox_delivery(delivery_status,created_at,event_id),INDEX ix_content_outbox_issue(issue_id,collection_name,created_at,event_id)) ENGINE=InnoDB;
INSERT IGNORE INTO roles VALUES('ADMIN'),('MAINTAINER'),('CONTRIBUTOR'),('BACKER');
INSERT IGNORE INTO labels VALUES(1,'parser'),(2,'security'),(3,'performance'),(4,'documentation'),(5,'ui'),(6,'regression');
